package com.coraline.tycoon;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class TycoonPhaseFiveGameTests {
    @GameTest(template="empty") public static void rolesLevelsAndSalariesAreIndependent(GameTestHelper t){
        t.assertTrue(TycoonWorkerType.values().length==16,"Missing worker role");for(var type:TycoonWorkerType.values()){var w=new CompoundTag();w.putString("Type",type.id());w.putInt("Unlocked",5);long previous=0;for(int rank=1;rank<=5;rank++){w.putInt("Operating",rank);long salary=TycoonWorkers.salaryMicros(w);t.assertTrue(salary>previous,"Operating level salary is not progressive");previous=salary;}w.putInt("Operating",1);t.assertTrue(TycoonWorkers.salaryMicros(w)<previous,"Downgrade still charges unlocked maximum");}t.assertTrue(TycoonWorkers.capacity(5)>TycoonWorkers.capacity(1),"Capacity does not improve");t.succeed();
    }
    @GameTest(template="empty") public static void noDiscretionarySpendingIsAuthorizedByDefault(GameTestHelper t){var h=new TycoonData.Home(UUID.randomUUID(),0);for(String flag:TycoonPolicies.FLAGS)t.assertFalse(TycoonPolicies.allowed(h,flag),"Spending/authority enabled without consent: "+flag);t.assertTrue(TycoonPolicies.number(h,"reserve")==10&&TycoonPolicies.number(h,"constructionPowerHour")==0,"Unsafe default budgets");t.succeed();}
    @GameTest(template="empty") public static void supplyCapacityAndFailedWithdrawalsConserveRealStock(GameTestHelper t){var h=new TycoonData.Home(UUID.randomUUID(),0);t.assertTrue(TycoonWarehouse.add(h,Items.COAL,4096),"Cannot fill base capacity");t.assertFalse(TycoonWarehouse.add(h,Items.REDSTONE,1),"Overfull stock accepted");t.assertFalse(TycoonWarehouse.take(h,Items.COAL,4097),"Overdraft accepted");t.assertTrue(TycoonWarehouse.count(h,Items.COAL)==4096,"Failed withdrawal removed stock");t.assertTrue(TycoonWarehouse.take(h,Items.COAL,64)&&TycoonWarehouse.total(h)==4032,"Real debit not reflected");t.succeed();}
    @GameTest(template="empty") public static void producedResourcesAreNeverImplicitlySpent(GameTestHelper t){var h=new TycoonData.Home(UUID.randomUUID(),0);var resources=new CompoundTag();resources.putLong("minecraft:coal",8);h.state.put("ProducedResources",resources);t.assertTrue(TycoonMachines.supply(h,Items.COAL)==0&&!TycoonMachines.takeSupply(h,Items.COAL,1),"Output stolen without opt-in");TycoonPolicies.state(h).putBoolean("useProducedSupplies",true);t.assertTrue(TycoonMachines.takeSupply(h,Items.COAL,3)&&resources.getLong("minecraft:coal")==5,"Opt-in does not debit real produced ingredients");t.succeed();}
    @GameTest(template="empty") public static void activeMinuteBudgetsDoNotResetOnRefresh(GameTestHelper t){var h=new TycoonData.Home(UUID.randomUUID(),0);h.state.putLong("ActiveTicks",1200);TycoonPolicies.spent(h,"food",9);t.assertTrue(!TycoonPolicies.budget(h,"food",2,10),"Overspend accepted");for(int i=0;i<10;i++)TycoonPolicies.state(h);t.assertTrue(!TycoonPolicies.budget(h,"food",2,10),"Menu refresh reset spending");h.state.putLong("ActiveTicks",72000);t.assertTrue(TycoonPolicies.budget(h,"food",2,10),"Next active hour not recognized");t.succeed();}
    @GameTest(template="empty") public static void warehouseAndPoliciesSurviveOwnerSave(GameTestHelper t){var data=new TycoonData();var h=data.home(UUID.randomUUID());TycoonWarehouse.add(h,Items.IRON_INGOT,17);TycoonPolicies.state(h).putBoolean("investing",true);h.state.putLong("SoulEssence",53);h.state.putLong("SoulFraction",123456);var worker=new CompoundTag();var id=UUID.randomUUID();worker.putUUID("Id",id);worker.putString("Type","accountant");worker.putInt("Operating",2);worker.putBoolean("Break",true);var workers=new CompoundTag();workers.put(id.toString(),worker);h.state.put("Workers",workers);var restored=TycoonData.load(data.save(new CompoundTag())).homes.get(h.owner);t.assertTrue(TycoonWarehouse.count(restored,Items.IRON_INGOT)==17&&TycoonPolicies.allowed(restored,"investing")&&restored.state.getLong("SoulFraction")==123456,"Economy/policies lost on save");t.assertTrue(TycoonWorkers.workers(restored).getCompound(id.toString()).getBoolean("Break"),"Paused worker resumed after reload");t.succeed();}
    @GameTest(template="empty") public static void machinePlansPreserveFiveLevelsAndRoundTrip(GameTestHelper t){for(boolean extractor:new boolean[]{false,true}){var plans=new HashSet<Map<?,?>>();for(int rank=1;rank<=5;rank++){var plan=TycoonMachines.plan(new BlockPos(30,90,20),extractor,rank);t.assertTrue(plan.equals(TycoonLandscape.decode(t.getLevel(),TycoonLandscape.encode(plan,new BlockPos(30,90,20)))),"Machine plan codec changed geometry");plans.add(plan);}t.assertTrue(plans.size()==5,"Levels share identical geometry");}t.succeed();}
    @GameTest(template="empty") public static void marketHistoryIsBoundedAndInspectionDoesNotReroll(GameTestHelper t){var market=new TycoonMarket();var before=market.save(new CompoundTag());for(var company:TycoonMarket.COMPANIES){market.history(company.id());market.price(company.id());}t.assertTrue(before.equals(market.save(new CompoundTag())),"Inspection rerolls market");for(int i=0;i<300;i++)market.advance();t.assertTrue(market.revision()==300,"Incorrect market revision");for(var company:TycoonMarket.COMPANIES)t.assertTrue(market.history(company.id()).length==240&&market.price(company.id())>=250000&&market.price(company.id())<=1000000000L,"Invalid bounded market history");t.succeed();}
    @GameTest(template="empty") public static void cashFlowIsMeasuredAndNotProjectedProfit(GameTestHelper t){var h=new TycoonData.Home(UUID.randomUUID(),0);TycoonFinance.record(h,"farm_income",800000);TycoonFinance.record(h,"payroll",-300000);TycoonFinance.record(h,"converter",-100000);h.state.putLong("ActiveTicks",1200);var report=TycoonFinance.view(h);t.assertTrue(report.getLong("MeasuredNetMinute")==400000&&report.getLong("MeasuredPayroll")==300000&&report.getLong("ProjectedFarmIncomeMinute")==0,"Cash flow fabricates projected revenue");t.succeed();}
    @GameTest(template="empty") public static void foodAccountingCommitsWithThePurchasePatch(GameTestHelper t){var h=new TycoonData.Home(UUID.randomUUID(),0);var patch=new CompoundTag();patch.putLong("SoulEssence",97);var flow=new CompoundTag();flow.putString("Category","food");flow.putLong("Micros",-3*TycoonSoulLedger.SCALE);patch.put("FinanceFlow",flow);TycoonTransactions.applyHomePatch(h,patch);h.state.putLong("ActiveTicks",1200);var view=TycoonFinance.view(h);t.assertTrue(h.state.getLong("SoulEssence")==97&&view.getLong("MeasuredFood")==3000000&&!h.state.contains("FinanceFlow"),"Paid food is missing from measured committed costs");t.succeed();}
    @GameTest(template="empty") public static void creditOverflowNeverLosesSoldValue(GameTestHelper t){var h=new TycoonData.Home(UUID.randomUUID(),0);h.state.putLong("SoulEssence",Long.MAX_VALUE);h.state.putLong("SoulFraction",999999);t.assertTrue(!TycoonSoulLedger.canCredit(h,1)&&!TycoonSoulLedger.creditMicros(h,1),"Overflow credit accepted");t.assertTrue(h.state.getLong("SoulEssence")==Long.MAX_VALUE&&h.state.getLong("SoulFraction")==999999,"Rejected credit changed balance");t.succeed();}
    @GameTest(template="empty") public static void allocationFindsRealRateImprovementWithoutMutatingWhileInspecting(GameTestHelper t){var h=new TycoonData.Home(UUID.randomUUID(),0);var low=new CompoundTag();low.putUUID("Id",UUID.randomUUID());low.putInt("Tier",1);low.putBoolean("Verified",true);var high=new CompoundTag();high.putUUID("Id",UUID.randomUUID());high.putInt("Tier",5);high.putBoolean("Verified",true);var farms=new CompoundTag();farms.put(low.getUUID("Id").toString(),low);farms.put(high.getUUID("Id").toString(),high);h.state.put("SoulFarms",farms);var soul=TycoonSouls.derive(h,TycoonCare.generate(UUID.randomUUID()),UUID.randomUUID());soul.putUUID("Farm",low.getUUID("Id"));var collection=new CompoundTag();collection.put(soul.getUUID("Id").toString(),soul);h.state.put("Souls",collection);var before=h.state.copy();var plan=TycoonSoulAllocation.best(h);t.assertTrue(!plan.isEmpty()&&plan.getLong("GainMicros")>0&&plan.getUUID("To").equals(high.getUUID("Id")),"Allocation missed a feasible production/resonance improvement");t.assertTrue(h.state.equals(before),"Inspection silently moved a soul");t.succeed();}
    @GameTest(template="empty") public static void candidatePoliciesDoNotReadUndiscoveredAptitude(GameTestHelper t){var a=TycoonCare.generate(UUID.randomUUID());var b=TycoonCare.generate(UUID.randomUUID());a.n.getCompound("Traits").putDouble("WorkerAptitude",1);b.n.getCompound("Traits").putDouble("WorkerAptitude",0);t.assertTrue(TycoonCandidateSelection.score(a,"Highest Worker Aptitude")==TycoonCandidateSelection.score(b,"Highest Worker Aptitude"),"Hiring preference exposed undiscovered aptitude");var observed=new CompoundTag();observed.putDouble("WorkerAptitudeEstimate",.8);a.n.put("CandidateObservations",observed);t.assertTrue(TycoonCandidateSelection.score(a,"Highest Worker Aptitude")>TycoonCandidateSelection.score(b,"Highest Worker Aptitude"),"Measured available information ignored");t.succeed();}
    private TycoonPhaseFiveGameTests(){}
}
